"""Verify the standard-mode assist override without assuming other hashed fields."""
import hashlib
import json
from pathlib import Path
pin = json.loads(Path('docs/reference/assist-window.json').read_text())
raw = Path('.cache/map11-definition.json').read_bytes()
assert hashlib.sha256(raw).hexdigest() == pin['sha256']
source = json.loads(raw)
assert pin['config'] in source[pin['mode']]['Configs']
assert source[pin['config']] == pin['record']
seconds = pin['record']['AssistDurationOverride']
assert seconds == 15
Path('src/content/assist-window.ts').write_text(
    '// Generated by tools/assets/export-assist-window.py from the pinned standard-mode config.\n'
    + f'export const ASSIST_WINDOW_SECONDS = {seconds:g};\n')
print('Verified standard-mode assist window: 15 seconds')
